-- Règles RLS existantes en production (pg_policies), recopiées à l'identique.
-- Celles des tables sans RLS sont aujourd'hui inactives ; elles s'activeront avec la phase 1.

CREATE POLICY "Seuls les admins peuvent créer des annulations" ON annulations_ventes FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Seuls les admins peuvent voir les annulations" ON annulations_ventes FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Consommations write production" ON consommations_atelier FOR ALL TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Consommations visible pour utilisateurs" ON consommations_atelier FOR SELECT TO public USING (auth.uid() IS NOT NULL);
CREATE POLICY "Création demandes pour tous" ON demandes FOR INSERT TO public WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Lecture demandes pour tous" ON demandes FOR SELECT TO public USING (true);
CREATE POLICY "Modification demandes pour tous" ON demandes FOR UPDATE TO public USING (auth.uid() IS NOT NULL);
CREATE POLICY "Utilisateurs peuvent créer leurs demandes groupées" ON demandes_groupees FOR INSERT TO authenticated WITH CHECK (auth.uid() = demandeur_id);
CREATE POLICY "Demandes groupées lisibles par tous les utilisateurs authentif" ON demandes_groupees FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admins et production peuvent modifier demandes groupées" ON demandes_groupees FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND (profiles.role = 'admin' OR profiles.role = 'employe_production')));
CREATE POLICY "update_demandes_groupees_valideurs" ON demandes_groupees FOR UPDATE TO public USING (auth.uid() IN (SELECT profiles.id FROM profiles WHERE profiles.role IN ('admin','employe_production')));
CREATE POLICY "Admins peuvent tout voir" ON depenses_comptables FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Admins peuvent supprimer" ON depenses_comptables FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Utilisateurs peuvent créer" ON depenses_comptables FOR INSERT TO authenticated WITH CHECK (utilisateur_id = auth.uid());
CREATE POLICY "Écriture pour admins et production" ON depenses_comptables FOR INSERT TO public WITH CHECK (auth.uid() IN (SELECT profiles.id FROM profiles WHERE profiles.role IN ('admin','employe_production')));
CREATE POLICY "Lecture pour utilisateurs connectés" ON depenses_comptables FOR SELECT TO public USING (auth.role() = 'authenticated');
CREATE POLICY "Utilisateurs voient leurs dépenses" ON depenses_comptables FOR SELECT TO authenticated USING (utilisateur_id = auth.uid());
CREATE POLICY "Mise à jour pour admins" ON depenses_comptables FOR UPDATE TO public USING (auth.uid() IN (SELECT profiles.id FROM profiles WHERE profiles.role = 'admin'));
CREATE POLICY "Utilisateurs modifient leurs dépenses" ON depenses_comptables FOR UPDATE TO authenticated USING (utilisateur_id = auth.uid());
CREATE POLICY "Admins et employés cuisine peuvent créer des lignes de vente" ON lignes_vente_cuisine FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "Admins et employés cuisine peuvent voir les lignes de vente" ON lignes_vente_cuisine FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "Modules modification super admin" ON modules FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.is_super_admin = true));
CREATE POLICY "Modules lecture pour tous" ON modules FOR SELECT TO public USING (true);
CREATE POLICY "Insertion mouvements stock pour admins et production" ON mouvements_stock FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Lecture mouvements stock pour tous" ON mouvements_stock FOR SELECT TO public USING (true);
CREATE POLICY "Admins et employés cuisine peuvent créer des mouvements" ON mouvements_stock_cuisine FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "Admins et employés cuisine peuvent voir les mouvements" ON mouvements_stock_cuisine FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "Users can delete own notifications" ON notifications FOR DELETE TO public USING (auth.uid() = destinataire_id);
CREATE POLICY "Authenticated users can create notifications" ON notifications FOR INSERT TO public WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Users can view own notifications" ON notifications FOR SELECT TO public USING (auth.uid() = destinataire_id);
CREATE POLICY "Users can update own notifications" ON notifications FOR UPDATE TO public USING (auth.uid() = destinataire_id);
CREATE POLICY "Only admins can view password logs" ON password_change_log FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Permissions modification super admin" ON permissions FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.is_super_admin = true));
CREATE POLICY "Permissions lecture admins" ON permissions FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND (profiles.is_super_admin = true OR profiles.role = 'admin')));
CREATE POLICY "Prix recettes admin write" ON prix_vente_recettes FOR ALL TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Prix recettes visible pour tous" ON prix_vente_recettes FOR SELECT TO public USING (actif = true);
CREATE POLICY "Création productions pour admin et production" ON productions FOR INSERT TO public WITH CHECK (auth.role() = 'authenticated' AND EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Lecture libre productions" ON productions FOR SELECT TO public USING (true);
CREATE POLICY "Lecture productions pour utilisateurs authentifiés" ON productions FOR SELECT TO public USING (auth.role() = 'authenticated');
CREATE POLICY "Admin peut tout faire produits" ON produits FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Création produits pour admin et production" ON produits FOR INSERT TO public WITH CHECK (auth.role() = 'authenticated' AND EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Lecture libre produits" ON produits FOR SELECT TO public USING (true);
CREATE POLICY "Lecture produits pour utilisateurs authentifiés" ON produits FOR SELECT TO public USING (auth.role() = 'authenticated');
CREATE POLICY "produits_cuisine_delete" ON produits_cuisine FOR DELETE TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "produits_cuisine_insert" ON produits_cuisine FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "produits_cuisine_select" ON produits_cuisine FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine','caissier','producteur')));
CREATE POLICY "produits_cuisine_update" ON produits_cuisine FOR UPDATE TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin')) WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Admins can insert profiles" ON profiles FOR INSERT TO authenticated WITH CHECK (auth.uid() IN (SELECT profiles_1.id FROM profiles profiles_1 WHERE profiles_1.role = 'admin' OR profiles_1.username = 'proprietaire'));
CREATE POLICY "Profiles are viewable by authenticated users" ON profiles FOR SELECT TO authenticated USING (true);
CREATE POLICY "Admins can update profiles" ON profiles FOR UPDATE TO authenticated USING (auth.uid() IN (SELECT profiles_1.id FROM profiles profiles_1 WHERE profiles_1.role = 'admin' OR profiles_1.username = 'proprietaire'));
CREATE POLICY "Creation recettes permissive" ON recettes FOR INSERT TO public WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Lecture recettes permissive" ON recettes FOR SELECT TO public USING (true);
CREATE POLICY "Modification recettes permissive" ON recettes FOR UPDATE TO public USING (auth.uid() IS NOT NULL);
CREATE POLICY "Référentiel modifiable par admins" ON referentiel_produits FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin' AND profiles.actif = true));
CREATE POLICY "Référentiel visible par tous" ON referentiel_produits FOR SELECT TO public USING (auth.role() = 'authenticated');
CREATE POLICY "Role permissions modification super admin" ON role_permissions FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.is_super_admin = true));
CREATE POLICY "Role permissions lecture admins" ON role_permissions FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND (profiles.is_super_admin = true OR profiles.role = 'admin')));
CREATE POLICY "Roles modification super admin" ON roles_custom FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.is_super_admin = true));
CREATE POLICY "Roles lecture admins" ON roles_custom FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND (profiles.is_super_admin = true OR profiles.role = 'admin')));
CREATE POLICY "Modification stock atelier pour admins et production" ON stock_atelier FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_production')));
CREATE POLICY "Stock atelier visible par tous" ON stock_atelier FOR SELECT TO authenticated USING (true);
CREATE POLICY "stock_cuisine_delete" ON stock_cuisine FOR DELETE TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "stock_cuisine_insert" ON stock_cuisine FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "stock_cuisine_select" ON stock_cuisine FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine','caissier','producteur')));
CREATE POLICY "stock_cuisine_update" ON stock_cuisine FOR UPDATE TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine'))) WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "User permissions modification super admin" ON user_permissions FOR ALL TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.is_super_admin = true));
CREATE POLICY "User permissions lecture" ON user_permissions FOR SELECT TO public USING (user_id = auth.uid() OR EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND (profiles.is_super_admin = true OR profiles.role = 'admin')));
CREATE POLICY "Seuls les admins peuvent mettre à jour les ventes" ON ventes FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin')) WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role = 'admin'));
CREATE POLICY "Admins et employés cuisine peuvent créer des ventes" ON ventes_cuisine FOR INSERT TO public WITH CHECK (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
CREATE POLICY "Admins et employés cuisine peuvent voir les ventes" ON ventes_cuisine FOR SELECT TO public USING (EXISTS (SELECT 1 FROM profiles WHERE profiles.id = auth.uid() AND profiles.role IN ('admin','employe_cuisine')));
